type: flow

readouts:
  ts: { kind: thread-summary, source: "thread", colorUnread: "#ef4444", label: "スレッド概要" }

lanes:
  unread: { x: 0, width: 220 }
  participants: { x: 260, width: 220 }
  activity: { x: 520, width: 260 }

